"""Additional original constructions; independent admission remains required."""
from core import *

@register('differentiation','abel-density-recovery','abel-integral-inversion','double-Abel-transform-and-Fubini','An unknown continuous density must be recovered from a singular integral. Composing the transform reveals a constant Beta kernel; differentiation then identifies the density uniquely.','Unlike direct moving-endpoint differentiation, the integrand is unknown and the singular upper endpoint prevents naive Leibniz substitution.',[{'caseId':'density-'+str(i),'coefficients':c,'at':str(a),'purpose':'Different density degree, nonzero power pattern and evaluation point; not scalar copies.'} for i,(c,a) in enumerate([([1,2,-1],R(1,2)),([2,-1,0,1],R(1,3)),([0,1,2,0,-1],R(2,3)),([1,0,-2,3],R(3,4)),([3,-2,0,0,1],R(1,4)),([1,1,-1,1,-1],R(2,5)),([0,2,1,0,0,1],R(3,5)),([2,0,1,-2,1],R(4,5)),([1,-1,2,0,-2,1],R(1,5)),([2,1,0,-1,0,2],R(2,7)),([0,1,-2,3,0,-1,1],R(3,7)),([1,0,1,0,-1,0,2],R(4,7))])],['Fubini theorem','integrable endpoint singularities','Beta integral','fundamental theorem of calculus'])
def abel(case):
 c=list(map(s.Integer,case['coefficients']));a=R(case['at']);f=sum(v*x**j for j,v in enumerate(c));C=[s.simplify(v*s.factorial(j)*s.sqrt(pi)/s.gamma(j+R(3,2))) for j,v in enumerate(c)];F=sum(v*x**(j+R(1,2)) for j,v in enumerate(C));A=s.diff(f,x).subs(x,a)
 u=s.symbols('u',positive=True)
 for j,v in enumerate(c):
  if v:ck('Exact singular transform of density monomial '+str(j),s.integrate(u**j/s.sqrt(1-u),(u,0,1))*v,C[j])
 ck('Composed kernel is exactly pi',s.integrate(1/s.sqrt(u*(1-u)),(u,0,1)),pi)
 recovered=sum(s.simplify(v*s.gamma(j+R(3,2))/(s.sqrt(pi)*s.factorial(j)))*x**j for j,v in enumerate(C));ck('Independent inverse coefficient calculation recovers the entire density',recovered,f)
 ck('Derivative of recovered density at the requested point',s.diff(recovered,x).subs(x,a),A)
 analytic('Abel inversion with continuous density',['The density is real continuous on the closed unit interval, hence bounded.','Both square-root endpoint singularities are integrable.'],['Apply the same transform again. Absolute Fubini is justified by the bound on the density and the finite positive double-kernel integral.','For0<=u<x, the inner integral from u to x of((t-u)(x-t))^(-1/2) is pi after t=u+(x-u)v. Hence the double transform is pi times integral0x f.','The fundamental theorem identifies f as the derivative of this known double transform divided by pi, proving uniqueness. Each displayed half-integral power therefore recovers the stated polynomial.'])
 wrong_no_beta=sum(v*x**j for j,v in enumerate(C));wrong_gamma=sum(s.simplify(v*s.gamma(j+R(1,2))/(s.sqrt(pi)*s.factorial(j)))*x**j for j,v in enumerate(C))
 pool=[(s.diff(wrong_no_beta,x).subs(x,a),'Treat the Abel power coefficient as the density coefficient'),(s.diff(wrong_gamma,x).subs(x,a),'Shift the inverse Gamma factor down by one'),(f.subs(x,a),'Return the recovered density instead of its derivative'),(A/2,'Retain an extra half from the square-root substitution'),(2*A,'Count the two composed endpoint singularities as two inverse transforms'),(-A,'Reverse the orientation in the inner Beta substitution'),(s.diff(f,x,2).subs(x,a),'Differentiate the recovered density one extra time')]
 return candidate(T('A real continuous function f on the closed unit interval satisfies ')+r'\int_0^x\frac{f(t)}{\sqrt{x-t}}\,\mathrm dt='+L(F)+r'\quad(0<x\le1).'+T('Find ')+r'f\prime('+L(a)+r').',A,pool,[T('Compose the given Abel transform with itself. Boundedness of the continuous density and integrability of both endpoint kernels justify absolute Fubini.'),r'\int_0^x\frac1{\sqrt{x-t}}\left(\int_0^t\frac{f(u)}{\sqrt{t-u}}\,\mathrm du\right)\mathrm dt=\int_0^xf(u)\left(\int_u^x\frac{\mathrm dt}{\sqrt{(t-u)(x-t)}}\right)\mathrm du',r'\int_u^x\frac{\mathrm dt}{\sqrt{(t-u)(x-t)}}=\int_0^1\frac{\mathrm dv}{\sqrt{v(1-v)}}=\pi',r'f(x)=\frac1\pi\frac{\mathrm d}{\mathrm dx}\int_0^x\frac{F(t)}{\sqrt{x-t}}\,\mathrm dt,\qquad F(x)='+L(F),r'\int_0^x\frac{t^j}{\sqrt{x-t}}\,\mathrm dt=\frac{4^{j+1}j!(j+1)!}{(2j+2)!}x^{j+1/2}\quad(j=0,1,\ldots)',r'f(x)='+L(f),r'f\prime('+L(a)+r')='+L(A)],'unknown-continuous-density-singular-transform-inverse')

@register('differentiation','laplace-moment-sharp-third','truncated-moment-positivity-and-atomic-attainment','nonnegative-polynomial-dual-bound-and-atomic-witness','Two derivative constraints fix two moments of an unknown probability measure. The sharp third derivative is a constrained moment problem, requiring a nonnegative polynomial certificate and an attaining measure.','The root-moment family uses finitely many equally weighted bounded coordinates. Here weights and support are free, so box-vertex enumeration is unavailable.',[{'caseId':'moments-'+str(i),'a':str(a),'b':str(b),'purpose':'Distinct first and second moments change the extremizing support and atom weights.'} for i,(a,b) in enumerate([(R(1,2),R(1,3)),(R(2,3),R(1,2)),(R(1,3),R(1,5)),(R(3,5),R(2,5)),(R(2,5),R(1,4)),(R(3,4),R(5,8)),(R(1,4),R(1,8)),(R(4,5),R(7,10)),(R(2,7),R(1,7)),(R(3,7),R(2,7)),(R(4,7),R(3,7)),(R(5,7),R(4,7))])],['probability measures','differentiation under an integral','nonnegative polynomial inequalities','sharpness'])
def laplace_moment(case):
 a=R(case['a']);b=R(case['b']);r=(a-b)/(1-a);q=(a-r)/(1-r);A=s.factor(b-(a-b)**2/(1-a));P=(1-x)*(x-r)**2
 condition('Strictly feasible moment pair',a*a<b<a<1,'This puts the second support point and both weights strictly inside their valid ranges.')
 condition('Atomic witness probabilities and support',0<r<1 and 0<q<1,'Atoms at r and1 have weights1-q andq.')
 ck('Atomic first moment',(1-q)*r+q,a);ck('Atomic second moment',(1-q)*r*r+q,b);ck('Atomic third moment',(1-q)*r**3+q,A)
 ck('Nonnegative dual polynomial expansion',s.expand(P),-x**3+(1+2*r)*x*x-(2*r+r*r)*x+r*r)
 ck('Integrated dual inequality has exactly the claimed endpoint',(1+2*r)*b-(2*r+r*r)*a+r*r,A)
 analytic('Sharp truncated Hausdorff moment bound',['The measure is a probability measure supported in[0,1]. All derivatives of its Laplace transform can be passed under the integral because the support is bounded.'],['The first and second derivative constraints give moments a and b. Integrate the nonnegative polynomial(1-t)(t-r)^2 to bound the third moment.','Choose r=(a-b)/(1-a); this is the value making a two-atom measure at r and1 satisfy both lower moments. Its positive weights are explicit.','That measure annihilates the dual polynomial, so it attains the upper bound. This proves a maximum over all probability measures, not merely over a guessed finite support.'])
 lower=b*b/a
 return candidate(T('Let mu range over probability measures supported in the closed unit interval, and set ')+r'f(x)=\int_0^1e^{-xt}\,\mathrm d\mu(t).\quad -f\prime(0)='+L(a)+r',\quad f^{\prime\prime}(0)='+L(b)+r'.'+T('Find the largest possible value of ')+r'-f^{\prime\prime\prime}(0).',A,[(lower,'Use the opposite endpoint moment bound from t(t-c)^2'),(b,'Use only t cubed at most t squared, ignoring the first moment'),(a**3,'Replace the measure by an inadmissible single atom'),(b+(a-b)**2/(1-a),'Reverse the sign of the variance correction'),(b-(a-b)**2/a,'Use the first moment instead of its complementary moment in the endpoint certificate'),(b-(a-b)**2,'Omit the complementary-mass normalization'),(A/3,'Return the cubic Taylor coefficient after only one factorial adjustment')],[r'm_j=\int_0^1t^j\,\mathrm d\mu(t),\qquad m_0=1,\quad m_1='+L(a)+r',\quad m_2='+L(b)+r',\quad -f^{\prime\prime\prime}(0)=m_3',r'r=\frac{m_1-m_2}{1-m_1}='+L(r)+r',\qquad (1-t)(t-r)^2\ge0\quad(0\le t\le1)',r'm_3\le(1+2r)m_2-(2r+r^2)m_1+r^2='+L(A),T('To prove attainment, put the following probabilities on the two displayed support points.'),r'\mu(\{1\})='+L(q)+r',\qquad\mu(\{'+L(r)+r'\})='+L(1-q),T('These weights are positive, sum to one, and give the required first and second moments. The nonnegative polynomial vanishes at both atoms, so the bound is exact.')],'Laplace-transform-third-derivative-two-moment-sharpness')

@register('differentiation','periodic-shift-derivative-bound','differential-shift-spectral-selection','Fourier-mode-annihilation-and-sharp-coefficient-norm','A differential equation with a half-period shift selects two hidden Fourier frequencies. One must prove that these are the only modes before optimizing the derivative and attaining the bound.','This is not a supplied finite polynomial Hilbert space: the admissible unknown functions are all periodic C2 solutions and spectral exclusion is essential.',[{'caseId':'frequencies-'+str(e)+'-'+str(o),'even':e,'odd':o,'purpose':'Coprime even/odd frequencies give distinct dimensionless spectral ratios.'} for e,o in [(2,1),(2,3),(2,5),(2,7),(4,1),(4,3),(4,5),(4,7),(6,1),(6,5),(6,7),(8,3)]],['periodic Fourier coefficients','integration by parts','Fourier uniqueness','Cauchy-Schwarz sharpness'])
def shift_spectrum(case):
 e=case['even'];o=case['odd'];alpha=R(e*e+o*o,2);beta=R(o*o-e*e,2);A=s.sqrt(e*e+o*o);witness=(e*s.sin(e*x)+o*s.sin(o*x))/A
 condition('The two spectral roots have the required parity and are distinct',e%2==0 and o%2==1 and s.gcd(e,o)==1,'Their ratio cannot be reduced by a common coordinate scaling.')
 ck('The attaining function solves the differential-shift equation',s.trigsimp(s.diff(witness,x,2)+alpha*witness-beta*witness.subs(x,x+pi)),0)
 ck('The attaining function has the exact norm',s.integrate(s.expand_trig(witness**2),(x,0,2*pi)),pi)
 ck('The attaining derivative reaches the proposed bound',s.diff(witness,x).subs(x,0),A)
 for j in range(0,max(e,o)+4):condition('Finite spectral sign check at mode '+str(j),(alpha-j*j-beta*(-1)**j==0)==(j in [e,o]),'The general parity formula reduces to e squared minus j squared for even j, and o squared minus j squared for odd j.')
 analytic('Complete Fourier exclusion and extremality',['The real function is C2 and2pi-periodic. Its shifted second-order equation can be bootstrapped to all derivative orders.'],['Integrate the equation against each exponential Fourier mode twice by parts; periodic boundary terms vanish. The shift multiplies mode k by(-1)^k.','The coefficient factor is e^2-k^2 for even k and o^2-k^2 for odd k, so only the four signed frequencies survive. Fourier uniqueness for continuous periodic functions identifies the function with that finite trigonometric sum.','Orthogonality converts the given integral to the squared Euclidean coefficient norm. The derivative is a linear functional of the two sine coefficients, whose norm is sqrt(e^2+o^2). The displayed function attains it.'])
 return candidate(T('Let f be a real twice continuously differentiable function of period ')+r'2\pi'+T(' satisfying ')+r'f^{\prime\prime}(x)+'+L(alpha)+r'f(x)='+L(beta)+r'f(x+\pi),\qquad\int_0^{2\pi}f(x)^2\,\mathrm dx=\pi.'+T('Find the largest possible value of ')+r'|f\prime(0)|.',A,[(s.sqrt(2*e*e+o*o),'Count both signs of the even Fourier mode as independent sine coefficients'),(s.sqrt(e*e+2*o*o),'Count both signs of the odd Fourier mode as independent sine coefficients'),(s.sqrt(abs(e*e-o*o)),'Subtract the two independent derivative energies'),(s.sqrt((e*e+o*o)/s.Integer(2)),'Use the complex-coefficient normalization for real sine coefficients'),(s.sqrt(2*(e*e+o*o)),'Omit the factor pi in real trigonometric orthogonality'),(s.sqrt(e*o),'Replace the sum of derivative energies by a geometric mean')],[T('A Fourier mode of index k receives the following factor. Integration by parts is valid because the function and its derivative are periodic.'),r'\left('+L(alpha-s.Symbol('k',integer=True)**2-beta*(-1)**s.Symbol('k',integer=True))+r'\right)\widehat f(k)=0',r'k\textnormal{ even}:\ '+str(e*e)+r'-k^2=0,\qquad k\textnormal{ odd}:\ '+str(o*o)+r'-k^2=0',T('Fourier uniqueness therefore leaves only these two frequencies.'),r'f(x)='+L(s.Symbol('a')*s.cos(e*x)+s.Symbol('b')*s.sin(e*x)+s.Symbol('c')*s.cos(o*x)+s.Symbol('d')*s.sin(o*x)),r'a^2+b^2+c^2+d^2=1,\qquad f\prime(0)='+L(e*s.Symbol('b')+o*s.Symbol('d')),r'|f\prime(0)|\le\sqrt{'+str(e*e)+r'+'+str(o*o)+r'}='+L(A),r'f(x)='+L(witness)+T(' attains equality and satisfies the stated equation and normalization.')],'unknown-periodic-differential-shift-spectrum-derivative-extremum')
